1	package validations
2	
3	import (
4		"encoding/json"
5		"fmt"
6	
7		"kena.bot/api-db-go/internal/domain/dbauditlog"
8		apierrors "kena.bot/api-db-go/internal/domain/errors"
9	)
10	
11	// Request DTOs + parsers for el router `/audit-log`. Vertical SIN
12	// contrapartida en el Node api-db (el registro de actividad del panel es
13	// nuevo), así que no hay un zod que mirrorear byte a byte. Se mantiene la
14	// MISMA forma de fallo que el resto del servicio (400 estructurado, contexto
15	// ZOD, primer campo que falla vía `zodItemError`) y se reutilizan los
16	// helpers compartidos del paquete: zodItemError, parseRequiredString,
17	// parseNullableBoundedString, parseEnumRequired, isJSONNull, jsonKind,
18	// bodyBindError, coerceLimit, coerceOffset — igual que
19	// moderation_flow_runs_validations.go.
20	
21	// auditLogStatusSet + auditLogStatusMsg — el enum cerrado de `status`, mismo
22	// estilo "Invalid option" del resto (p.ej. flowRunStatusMsg). Construido a
23	// partir de las constantes de dbauditlog (no de `Statuses`, para que el
24	// `map[string]bool` que piden parseEnumRequired/el filtro de listado quede
25	// como literal, igual que flowRunStatusSet).
26	var auditLogStatusSet = map[string]bool{
27		dbauditlog.StatusOK:    true,
28		dbauditlog.StatusError: true,
29	}
30	
31	const auditLogStatusMsg = `Invalid option: expected one of "ok"|"error"`
32	
33	// auditLogChangesMaxBytes es el techo de tamaño serializado que
34	// ParseAuditLogCreate exige a `changes`: un documento libre, pero no
35	// ilimitado — un blob enorme inflaría silenciosamente la colección (y la
36	// poda por servidor, que cuenta FILAS, no bytes).
37	const auditLogChangesMaxBytes = 16 * 1024
38	
39	// ─── GET /audit-log (list) ─────────────────────────────────────────────────
40	
41	// ParseAuditLogListQuery mirrors los filtros de
42	// `GET /audit-log?guild_id=&bot_id=&actor_id=&action=&status=&limit=&offset=`.
43	// `guild_id` es OBLIGATORIO (a diferencia de dbflowrun.ListParams, donde
44	// hasta guild_id es opcional); `bot_id`/`actor_id`/`action` son filtros de
45	// texto libre opcionales; `status` opcional se valida contra el enum
46	// cerrado; `limit` por defecto 25 (techo 100, vía el coerceLimit
47	// compartido), `offset` por defecto 0.
48	func ParseAuditLogListQuery(guildID, botID, actorID, action, status, limitRaw, offsetRaw string) (dbauditlog.ListFilter, int, int, *apierrors.CustomError) {
49		if guildID == "" {
50			return dbauditlog.ListFilter{}, 0, 0, zodItemError("guild_id is required", "guild_id")
51		}
52		filter := dbauditlog.ListFilter{GuildID: guildID}
53		if botID != "" {
54			v := botID
55			filter.BotID = &v
56		}
57		if actorID != "" {
58			v := actorID
59			filter.ActorID = &v
60		}
61		if action != "" {
62			v := action
63			filter.Action = &v
64		}
65		if status != "" {
66			if !auditLogStatusSet[status] {
67				return filter, 0, 0, zodItemError(auditLogStatusMsg, "status")
68			}
69			v := status
70			filter.Status = &v
71		}
72	
73		limitPtr, verr := coerceLimit(limitRaw, 100)
74		if verr != nil {
75			return filter, 0, 0, verr
76		}
77		offsetPtr, verr := coerceOffset(offsetRaw)
78		if verr != nil {
79			return filter, 0, 0, verr
80		}
81		limit := 25
82		if limitPtr != nil {
83			limit = *limitPtr
84		}
85		offset := 0
86		if offsetPtr != nil {
87			offset = *offsetPtr
88		}
89		return filter, limit, offset, nil
90	}
91	
92	// ─── POST /audit-log (create) ──────────────────────────────────────────────
93	
94	// ParseAuditLogCreate mirrors el body de creación de una fila:
95	// `{bot_id,guild_id,actor_id,actor_label?,action,target_type?,target_id?,
96	// status,changes?,route?}`. `bot_id`/`guild_id`/`actor_id`/`action`/`status`
97	// son REQUERIDOS; `action` además no puede ir vacía y tiene un techo de 128
98	// caracteres; el resto son opcionales y nullable. Orden de campos: bot_id,
