174	// ParseInfractionListQuery mirrors `infractionListQuery`. Shape order: limit,
175	// offset, bot_id, guild_id, user_id, moderator_id, type, status, source,
176	// case_number, expires_before, created_after, types, statuses. limit
177	// `.min(1).max(200)` (reuses coerceTrackErrorLimit); case_number
178	// `z.coerce.number().int().positive()` (reuses coercePositive); expires_before y
179	// created_after `z.string().datetime({ offset: true })`.
180	// An EMPTY query string is treated as ABSENT.
181	//
182	// `types` y `statuses` son listas CSV (`warn,mute`) que CONVIVEN con los filtros
183	// singulares `type` / `status`: si llegan los dos, se acumulan en el WHERE con
184	// AND. Cada elemento se valida contra el MISMO set que el singular y falla con el
185	// mismo mensaje de enum. `created_after` es lo que necesita el escalado automático
186	// para acotar su ventana de conteo.
187	func ParseInfractionListQuery(limitRaw, offsetRaw, botID, guildID, userID, moderatorID, typ, status, source, caseNumberRaw, expiresBefore, createdAfter, typesRaw, statusesRaw string) (dbinfraction.ListParams, *apierrors.CustomError) {
188		var p dbinfraction.ListParams
189		limitPtr, verr := coerceTrackErrorLimit(limitRaw)
190		if verr != nil {
191			return p, verr
192		}
193		p.Limit = limitPtr
194		offsetPtr, verr := coerceOffset(offsetRaw)
195		if verr != nil {
196			return p, verr
197		}
198		p.Offset = offsetPtr
199		if botID != "" {
200			v := botID
201			p.BotID = &v
202		}
203		if guildID != "" {
204			v := guildID
205			p.GuildID = &v
206		}
207		if userID != "" {
208			v := userID
209			p.UserID = &v
210		}
211		if moderatorID != "" {
212			v := moderatorID
213			p.ModeratorID = &v
214		}
215		if typ != "" {
216			if !infractionTypeSet[typ] {
217				return p, zodItemError(infractionTypeMsg, "type")
218			}
219			v := typ
220			p.Type = &v
221		}
222		if status != "" {
223			if !infractionStatusSet[status] {
224				return p, zodItemError(infractionStatusMsg, "status")
225			}
226			v := status
227			p.Status = &v
228		}
229		if source != "" {
230			if !infractionSourceSet[source] {
231				return p, zodItemError(infractionSourceMsg, "source")
232			}
233			v := source
234			p.Source = &v
235		}
236		caseNumberPtr, verr := coercePositive(caseNumberRaw, "case_number")
237		if verr != nil {
238			return p, verr
239		}
240		p.CaseNumber = caseNumberPtr
241		if expiresBefore != "" {
242			if !infractionOffsetDateTimeRe.MatchString(expiresBefore) {
243				return p, zodItemError("Invalid ISO datetime", "expires_before")
244			}
245			v := expiresBefore
246			p.ExpiresBefore = &v
247		}
248		// created_after: mismo formato y misma regex que expires_before.
249		if createdAfter != "" {
250			if !infractionOffsetDateTimeRe.MatchString(createdAfter) {
251				return p, zodItemError("Invalid ISO datetime", "created_after")
252			}
253			v := createdAfter
254			p.CreatedAfter = &v
255		}
256		types, verr := parseInfractionEnumCSV(typesRaw, infractionTypeSet, infractionTypeMsg, "types")
257		if verr != nil {
258			return p, verr
259		}
260		p.Types = types
261		statuses, verr := parseInfractionEnumCSV(statusesRaw, infractionStatusSet, infractionStatusMsg, "statuses")
262		if verr != nil {
263			return p, verr
264		}
265		p.Statuses = statuses
266		return p, nil
267	}
