269	// parseInfractionEnumCSV convierte un filtro CSV (`warn,mute`) en la lista de
270	// valores validados contra `set`. Los elementos vacíos se IGNORAN (`warn,,mute` y
271	// `warn, mute` dan ambos ["warn","mute"]), y un CSV entero vacío —o que sólo
272	// tenga separadores— devuelve nil, es decir, filtro AUSENTE. El primer elemento
273	// que no esté en el set corta con el MISMO mensaje de enum que el filtro singular
274	// equivalente, sólo que con la propiedad en plural.
275	func parseInfractionEnumCSV(raw string, set map[string]bool, msg, property string) ([]string, *apierrors.CustomError) {
276		if raw == "" {
277			return nil, nil
278		}
279		out := []string{}
280		for _, part := range strings.Split(raw, ",") {
281			v := strings.TrimSpace(part)
282			if v == "" {
283				continue
284			}
285			if !set[v] {
286				return nil, zodItemError(msg, property)
287			}
288			out = append(out, v)
289		}
290		if len(out) == 0 {
291			return nil, nil
292		}
293		return out, nil
294	}
