324	// ─── PATCH /:id (update) ──────────────────────────────────────────────────
325	
326	// ParseInfractionUpdate mirrors `infractionUpdateBody` (NOT strict; every field
327	// optional). Builds the present-columns map (a present null → a nil map value →
328	// SQL NULL). An empty body yields an empty map; the repo turns that into
329	// `findById(id)`, matching Node's `if sets.length === 0 return findById(id)`.
330	// Fields validate in zod declaration order: reason, duration_ms, expires_at,
331	// status, mechanism, applied_at, revoked_at, revoked_by, revoke_reason.
332	func ParseInfractionUpdate(body []byte) (map[string]any, *apierrors.CustomError) {
333		var raw struct {
334			Reason       json.RawMessage `json:"reason"`
335			DurationMs   json.RawMessage `json:"duration_ms"`
336			ExpiresAt    json.RawMessage `json:"expires_at"`
337			Status       json.RawMessage `json:"status"`
338			Mechanism    json.RawMessage `json:"mechanism"`
339			AppliedAt    json.RawMessage `json:"applied_at"`
340			RevokedAt    json.RawMessage `json:"revoked_at"`
341			RevokedBy    json.RawMessage `json:"revoked_by"`
342			RevokeReason json.RawMessage `json:"revoke_reason"`
343		}
344		if err := json.Unmarshal(body, &raw); err != nil {
345			return nil, bodyBindError(err)
346		}
347		set := map[string]any{}
348		// reason: z.string().max(2000).nullable().optional().
349		if verr := addMetaStringField(set, "reason", raw.Reason, "reason", 2000, false); verr != nil {
350			return nil, verr
351		}
352		// duration_ms: z.number().int().nonnegative().nullable().optional().
353		if verr := addNullableIntField(set, "duration_ms", raw.DurationMs, "duration_ms", 0, 0); verr != nil {
354			return nil, verr
355		}
356		// expires_at: z.string().datetime({ offset: true }).nullable().optional().
357		if verr := addNullableOffsetDatetimeField(set, "expires_at", raw.ExpiresAt, "expires_at"); verr != nil {
358			return nil, verr
359		}
360		// status: z.enum(statusValues).optional() (NOT nullable → present null is an enum error).
361		if verr := addOptionalEnumField(set, "status", raw.Status, infractionStatusSet, infractionStatusMsg, "status"); verr != nil {
362			return nil, verr
363		}
364		// mechanism: z.enum(mechanismValues).nullable().optional().
365		if verr := addNullableEnumField(set, "mechanism", raw.Mechanism, infractionMechanismSet, infractionMechanismMsg, "mechanism"); verr != nil {
366			return nil, verr
367		}
368		// applied_at / revoked_at: z.string().datetime({ offset: true }).nullable().optional().
369		if verr := addNullableOffsetDatetimeField(set, "applied_at", raw.AppliedAt, "applied_at"); verr != nil {
370			return nil, verr
371		}
372		if verr := addNullableOffsetDatetimeField(set, "revoked_at", raw.RevokedAt, "revoked_at"); verr != nil {
373			return nil, verr
374		}
375		// revoked_by: z.string().max(32).nullable().optional().
376		if verr := addMetaStringField(set, "revoked_by", raw.RevokedBy, "revoked_by", 32, false); verr != nil {
377			return nil, verr
378		}
379		// revoke_reason: z.string().max(2000).nullable().optional().
380		if verr := addMetaStringField(set, "revoke_reason", raw.RevokeReason, "revoke_reason", 2000, false); verr != nil {
381			return nil, verr
382		}
383		return set, nil
384	}
