386	// ─── field helpers (moderation-specific) ──────────────────────────────────
387	
388	// parseNullableBoundedString mirrors an OPTIONAL, NULLABLE `z.string()[.min][.max]`
389	// field returning a pointer: absent OR present null → nil (→ the repo binds SQL
390	// NULL, since absent and null both feed the Node repo's `?? null`); wrong type →
391	// "received X"; then the length bounds; else the value. A minLen/maxLen of 0
392	// disables that bound.
393	func parseNullableBoundedString(raw json.RawMessage, property string, minLen, maxLen int) (*string, *apierrors.CustomError) {
394		if raw == nil || isJSONNull(raw) {
395			return nil, nil
396		}
397		var s string
398		if err := json.Unmarshal(raw, &s); err != nil {
399			return nil, zodItemError("Invalid input: expected string, received "+jsonKind(raw), property)
400		}
401		if verr := validateStringLen(s, property, minLen, maxLen); verr != nil {
402			return nil, verr
403		}
404		return &s, nil
405	}
406	
407	// parseOptionalEnum mirrors an OPTIONAL, non-nullable `z.enum(values)` field
408	// returning a pointer: absent → nil; a listed string → the value; anything else
409	// (including a present null) → the enum message.
410	func parseOptionalEnum(raw json.RawMessage, values map[string]bool, msg, property string) (*string, *apierrors.CustomError) {
411		if raw == nil {
412			return nil, nil
413		}
414		if jsonKind(raw) == "string" {
415			var s string
416			if err := json.Unmarshal(raw, &s); err == nil && values[s] {
417				return &s, nil
418			}
419		}
420		return nil, zodItemError(msg, property)
421	}
422	
423	// parseNullableEnum mirrors an OPTIONAL, NULLABLE `z.enum(values)` field returning
424	// a pointer: absent OR present null → nil (both bind SQL NULL via the repo's
425	// `?? null`); a listed string → the value; anything else → the enum message.
426	func parseNullableEnum(raw json.RawMessage, values map[string]bool, msg, property string) (*string, *apierrors.CustomError) {
427		if raw == nil || isJSONNull(raw) {
428			return nil, nil
429		}
430		if jsonKind(raw) == "string" {
431			var s string
432			if err := json.Unmarshal(raw, &s); err == nil && values[s] {
433				return &s, nil
434			}
435		}
436		return nil, zodItemError(msg, property)
437	}
438	
439	// parseNullableInt64NonNeg mirrors `z.number().int().nonnegative().nullable()
440	// .optional()` returning a *int64 (the column is BIGINT): absent OR present null
441	// → nil; non-number → "received X"; non-integer → "received number"; below 0 →
442	// too_small (>=0); else the value.
443	func parseNullableInt64NonNeg(raw json.RawMessage, property string) (*int64, *apierrors.CustomError) {
444		if raw == nil || isJSONNull(raw) {
445			return nil, nil
446		}
447		var f float64
448		if err := json.Unmarshal(raw, &f); err != nil {
449			return nil, zodItemError("Invalid input: expected number, received "+jsonKind(raw), property)
450		}
451		if math.IsInf(f, 0) || f != math.Trunc(f) {
452			return nil, zodItemError("Invalid input: expected int, received number", property)
453		}
454		if f < 0 {
455			return nil, zodItemError("Too small: expected number to be >=0", property)
456		}
457		v := int64(f)
458		return &v, nil
459	}
460	
461	// parseNullableOffsetDatetime mirrors `z.string().datetime({ offset: true })
462	// .nullable().optional()` returning a pointer to the validated ISO string (bound
463	// to the timestamptz): absent OR present null → nil; non-string → "received X"; a
464	// string failing the offset-datetime format → `Invalid ISO datetime`; else the
465	// value.
466	func parseNullableOffsetDatetime(raw json.RawMessage, property string) (*string, *apierrors.CustomError) {
467		if raw == nil || isJSONNull(raw) {
468			return nil, nil
469		}
470		var s string
471		if err := json.Unmarshal(raw, &s); err != nil {
472			return nil, zodItemError("Invalid input: expected string, received "+jsonKind(raw), property)
473		}
474		if !infractionOffsetDateTimeRe.MatchString(s) {
475			return nil, zodItemError("Invalid ISO datetime", property)
476		}
477		return &s, nil
478	}
479	
480	// parseNullableRecord mirrors `z.record(z.string(), z.unknown()).nullable()
481	// .optional()` returning the raw jsonb bytes (the repo binds `JSON.stringify(v ??
482	// {})`): absent OR present null → nil (→ the repo binds `{}`); a JSON object → the
483	// raw bytes; any other type → the record type error. `z.unknown()` accepts any
484	// value, so no per-key validation is needed.
485	func parseNullableRecord(raw json.RawMessage, property string) (json.RawMessage, *apierrors.CustomError) {
486		if raw == nil || isJSONNull(raw) {
487			return nil, nil
488		}
489		if jsonKind(raw) != "object" {
490			return nil, zodItemError("Invalid input: expected record, received "+jsonKind(raw), property)
491		}
492		return raw, nil
493	}
494	
495	// addNullableOffsetDatetimeField mirrors an OPTIONAL, NULLABLE
496	// `z.string().datetime({ offset: true })` PATCH field: absent → skip; present
497	// null → set NULL; non-string → "received X"; a string failing the
498	// offset-datetime format → `Invalid ISO datetime`; else set the
499	// (timestamptz-bindable) string.
500	func addNullableOffsetDatetimeField(set map[string]any, col string, raw json.RawMessage, property string) *apierrors.CustomError {
501		if raw == nil {
502			return nil
503		}
504		if isJSONNull(raw) {
505			set[col] = nil
506			return nil
507		}
508		var s string
509		if err := json.Unmarshal(raw, &s); err != nil {
510			return zodItemError("Invalid input: expected string, received "+jsonKind(raw), property)
511		}
512		if !infractionOffsetDateTimeRe.MatchString(s) {
513			return zodItemError("Invalid ISO datetime", property)
514		}
515		set[col] = s
516		return nil
517	}
518

