package handlers_test

import (
	"context"
	"errors"
	"sync"
	"testing"

	"github.com/gofiber/fiber/v3"

	"kena.bot/api-db-go/internal/application/handlers"
	"kena.bot/api-db-go/internal/application/middlewares"
	"kena.bot/api-db-go/internal/application/routers"
	"kena.bot/api-db-go/internal/domain/dbguild"
	"kena.bot/api-db-go/internal/domain/mocks"
	"kena.bot/api-db-go/internal/infrastructure/mongorepo"
)

// The dashboard PATCH on `radio_mode.enabled` is the ONLY writer of the 24/7
// flag on Redis db 8. It was documented in `module_validations.go` and never
// wired: Mongo committed and the flag stayed as it was, so a server that left
// 24/7 kept its player keys immortal until a restart. These tests pin the
// side-effect down so it cannot silently disappear again.

type persistenceCall struct {
	botID, guildID string
	persistent     bool
}

type fakePersistenceWriter struct {
	mu    sync.Mutex
	calls []persistenceCall
	err   error
}

func (f *fakePersistenceWriter) SetPlayerPersistent(_ context.Context, botID, guildID string, persistent bool) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.calls = append(f.calls, persistenceCall{botID: botID, guildID: guildID, persistent: persistent})
	return f.err

package handlers

import (
	"context"
	"reflect"
	"strings"

	"github.com/gofiber/fiber/v3"
	"github.com/rs/zerolog/log"

	"kena.bot/api-db-go/internal/domain/dbguild"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
	"kena.bot/api-db-go/internal/domain/validations"
	"kena.bot/api-db-go/internal/infrastructure/mongorepo"
	"kena.bot/api-db-go/internal/shared/result"
)

// Music field whitelist. Must match the keys of `dbguild.ModuleMusic`
// 1:1 (otherwise a typo in the path would 200 with `null` instead of
// 400). Kept as a sorted-slice comparison via a map for O(1) lookup.
var musicFieldWhitelist = map[string]struct{}{
	"schema_version":       {},
	"enabled":              {},
	"enabled_since":        {},
	"max_song_duration":    {},
	"loop":                 {},
	"volume":               {},
	"radio_mode":           {},
	"message_retention":    {},
	"pinned_now_playing":   {},
	"voice_status_enabled": {},
	"bot_pool_enabled":     {},
	"enhanced_search":      {},
	"auto_delete_commands": {},
	"audio_quality":        {},
	"commands_global":      {},
	"commands":             {},
	"text_channels":        {},
	"voice_channels":       {},
	"dj":                   {},
	"recommended_artists":  {},
}

// ModuleMusicHandler wires the three music endpoints behind a single
// struct so the router can mount them with a single instance.
//
// Mirrors `module-music-controller.ts` in the Node service.
type ModuleMusicHandler struct {
	Repo mongorepo.ModuleMusicRepo
	// Lavalink is nil only when a caller has no db-8 writer at all (the tests).
	// A FAILED dial does NOT arrive here as nil: main.go wraps the nil client in
	// a nil-safe cache, so the call still happens and returns
	// ErrLavalinkUnavailable, which the PATCH logs. That is deliberate — a
	// toggle that did not reach Redis must leave a per-request trace, not just
	// the one boot line. This side-effect went unnoticed for exactly that
	// reason: no signal at the point of failure.
	Lavalink PlayerPersistenceWriter
}

// PlayerPersistenceWriter is the db-8 side-effect the music PATCH needs to keep
// Redis in step with `radio_mode.enabled`. An interface rather than the concrete
// *redis.LavalinkCache so the handler stays testable and so a failed dial can be
// wired as nil.
type PlayerPersistenceWriter interface {
	SetPlayerPersistent(ctx context.Context, botID, guildID string, persistent bool) error
}

// NewModuleMusicHandler builds the handler. `lavalink` is the optional db-8
// writer; pass nil to skip the 24/7 propagation. It is a REQUIRED parameter
// rather than a field callers may forget to set, on purpose: the defect this
// fixes was precisely that the side-effect was documented but never wired.
func NewModuleMusicHandler(repo mongorepo.ModuleMusicRepo, lavalink PlayerPersistenceWriter) *ModuleMusicHandler {
	return &ModuleMusicHandler{Repo: repo, Lavalink: lavalink}
}

// Get mirrors `getModuleMusicController`. Returns the full music subdoc
// (default-filled) with source headers stamped.
func (h *ModuleMusicHandler) Get(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleMusic]()
	ctx := c.Context()

	sourced, err := h.Repo.FindModule(ctx, c.Params("bot_id"), c.Params("guild_id"))
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		// data:null parity — the Node getModuleMusicController runs
		// applySourceAndStash(sourced{data:null}) before throwing
		// MODULE_NOT_FOUND, so the envelope carries `"data":null`.
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	d := sourced.Data
	r.SetData(&d)
	r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	return reply(c, r)
}

// GetField mirrors `getModuleMusicFieldController`. Returns a single
// field value via `data: <single value>`. Returns 400 MODULE_NOT_FOUND
// when the guild has no module music yet.
// GetRadioModeGuilds lists this bot's guilds with 24/7 enabled and the channel
// each one is configured to sit in.
//
// Bot-scoped, so it hangs off `/bots/:bot_id/modules/music/...` rather than the
// per-guild prefix — same shape as the modmail `active-guild` endpoint.
//
// An empty list is a 200 with `data: []`, NOT an error: "this bot has no 24/7
// guilds" is a perfectly ordinary answer, and the caller (the music module's
// boot reconciliation) has to be able to tell it apart from "the query failed"
// — if it could not, a database hiccup would look like "nobody wants 24/7" and
// the reconciliation would silently do nothing.
func (h *ModuleMusicHandler) GetRadioModeGuilds(c fiber.Ctx) error {
	r := result.New[any]()

	guilds, err := h.Repo.FindRadioModeGuilds(c.Context(), c.Params("bot_id"))
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}

	r.SetData(guilds)
	// Literal en vez de la constante de `mongo`: este handler sólo depende de
	// `mongorepo` (interfaces) para poder testearse con fakes, e importar el
	// paquete de infraestructura sólo por una cadena rompería esa separación.
	// El valor es el mismo que estampa el repositorio en sus lecturas de Mongo.
	r.SetSource(result.SourceDB, "mongo.guild.module_music")
	return reply(c, r)
}

func (h *ModuleMusicHandler) GetField(c fiber.Ctx) error {
	r := result.New[any]()
	ctx := c.Context()

	field := c.Params("field")
	if _, ok := musicFieldWhitelist[field]; !ok {
		r.AddError(apierrors.Validation("field must be one of the music keys", ""))
		return reply(c, r)
	}

	sourced, err := h.Repo.FindField(ctx, c.Params("bot_id"), c.Params("guild_id"), field)
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced == nil || sourced.Data == nil {
		// data:null parity — the Node getModuleMusicFieldController runs
		// applySourceAndStash(sourced{data:null}) before throwing
		// MODULE_NOT_FOUND. The `any` payload already omits `data` when
		// unset, so stamp an explicit null.
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	r.SetData(sourced.Data)
	r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	return reply(c, r)
}

// Patch mirrors `patchModuleMusicController`. Strict body — unknown
// JSON keys fail `c.Bind().Body(&body)` with a TypeMismatch error.
//
// The Node service runs a `GuildRepository.checkGuildExists` first.
// We rely on Mongo's no-document response when the guild is missing;
// the repository returns `nil, nil` and the handler emits UNKNOWN_ERROR.
func (h *ModuleMusicHandler) Patch(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleMusic]()
	ctx := c.Context()

	var body validations.UpdateModuleMusicBody
	if err := c.Bind().Body(&body); err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	set := body.Set()
	if len(set) == 0 {
		// Empty body or no applicable fields → 400. Strict parity with
		// the bots-guilds Update handler.
		r.AddError(apierrors.Unknown(""))
		return reply(c, r)
	}

	sourced, err := h.Repo.Update(ctx, c.Params("bot_id"), c.Params("guild_id"), set)
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		// data:null parity — the Node patchModuleMusicController runs
		// applySourceAndStash(sourced{data:null}) before throwing
		// UNKNOWN_ERROR on the update-null branch (a missing guild makes
		// Mongo return no document). Keep the UNKNOWN_ERROR code; only the
		// data-presence changes.
		r.SetData(nil)
		r.AddError(apierrors.Unknown(""))
		return reply(c, r)
	}

	// Side-effect on db 8. The dashboard just toggled 24/7, and Redis holds the
	// flag that keeps a live player's keys out of the TTL cycle; without this the
	// PATCH updated Mongo and left the flag lying. Best-effort by design: Mongo is
	// the source of truth and has already committed, so a Redis failure must not
	// turn a successful PATCH into a 500 — and `PlayerStart` resyncs the flag from
	// `radio_mode.enabled` on the next player start regardless.
	if enabled := body.RadioModeEnabled(); enabled != nil && h.Lavalink != nil {
		botID, guildID := c.Params("bot_id"), c.Params("guild_id")
		if err := h.Lavalink.SetPlayerPersistent(ctx, botID, guildID, *enabled); err != nil {
			log.Warn().Err(err).
				Str("bot_id", botID).
				Str("guild_id", guildID).
				Bool("radio_mode_enabled", *enabled).
				Msg("radio_mode PATCH committed to mongo but the 24/7 flag on db 8 was not updated")
		}
	}
	d := sourced.Data
	r.SetData(&d)
	r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	return reply(c, r)
}

// ensureMusicWhitelistMatchesType is a build-time assertion that the
// musicFieldWhitelist map covers every JSON-tagged field of ModuleMusic.
// Run at init via blank assignment; fails compilation if drift occurs.
var _ = func() bool {
	want := map[string]struct{}{}
	t := reflect.TypeOf(struct {
		SchemaVersion      int      `json:"schema_version"`
		Enabled            bool     `json:"enabled"`
		EnabledSince       any      `json:"enabled_since"`
		MaxSongDuration    int      `json:"max_song_duration"`
		Loop               string   `json:"loop"`
		Volume             int      `json:"volume"`
		RadioMode          any      `json:"radio_mode"`
		MessageRetention   bool     `json:"message_retention"`
		PinnedNowPlaying   bool     `json:"pinned_now_playing"`
		VoiceStatusEnabled bool     `json:"voice_status_enabled"`
		BotPoolEnabled     bool     `json:"bot_pool_enabled"`
		EnhancedSearch     bool     `json:"enhanced_search"`
		AutoDeleteCommands []string `json:"auto_delete_commands"`
		AudioQuality       string   `json:"audio_quality"`
		CommandsGlobal     any      `json:"commands_global"`
		Commands           any      `json:"commands"`
		TextChannels       any      `json:"text_channels"`
		VoiceChannels      any      `json:"voice_channels"`
		DJ                 any      `json:"dj"`
		RecommendedArtists []string `json:"recommended_artists"`
	}{})
	for i := 0; i < t.NumField(); i++ {
		tag := strings.SplitN(t.Field(i).Tag.Get("json"), ",", 2)[0]
		if tag != "" {
			want[tag] = struct{}{}
		}
	}
	if len(want) != len(musicFieldWhitelist) {
		return false
	}
	for k := range want {
		if _, ok := musicFieldWhitelist[k]; !ok {
			return false
		}
	}
	return true
}()

// Package handlers houses every HTTP handler the application exposes.
package handlers

import (
	stderrors "errors"

	"github.com/go-playground/validator/v10"
	"github.com/gofiber/fiber/v3"

	"kena.bot/api-db-go/internal/domain/errors"
	"kena.bot/api-db-go/internal/domain/validations"
)

// BuildError mirrors the Node `captureErrors` helper: it converts any error
// surfaced by a handler into a CustomError suitable for embedding in the
// ResultData envelope. Special cases:
//   - *CustomError values pass through unchanged.
//   - Mongo duplicate-key violations become the 409 DUPLICATE_KEY payload.
//   - validator.ValidationErrors map to a ZOD-context VALIDATION error with
//     a structured `issues` metadata array (paridad with Zod errors).
//   - anything else becomes a 500 UNKNOWN-shaped CustomError so clients
//     always receive a stable shape.
func BuildError(err error) *errors.CustomError {
	if err == nil {
		return nil
	}
	var custom *errors.CustomError
	if stderrors.As(err, &custom) {
		return custom
	}
	if errors.IsDuplicateKey(err) {
		return errors.DuplicateKey()
	}
	var verrs validator.ValidationErrors
	if stderrors.As(err, &verrs) {
		issues := validations.CollectValidationErrors(err)
		return errors.New(errors.Props{
			Message:    "Validation error",
			Context:    errors.ContextZod,
			Type:       errors.TypeValidation,
			Metadata:   map[string]any{"issues": issues},
			StatusCode: errors.StatusBadRequest,
		})
	}
	return errors.New(errors.Props{
		Message:    err.Error(),
		Type:       errors.TypeInternal,
		Context:    errors.ContextSystem,
		StatusCode: errors.StatusInternalServerError,
	})
}

// WriteError wraps BuildError with the side-effect the Node side performs
// via `captureErrors` + `setContextErrorHeaders`: append the error to the
// envelope AND stamp the `x-error-type` header with the first error's
// context so clients can branch on it without parsing the JSON body.
//
// Returns the same `*CustomError` BuildError produces so callers can keep
// their existing `r.AddError(BuildError(err))` flow if they don't need the
// header.
func WriteError(c fiber.Ctx, r sourcedView, err error) *errors.CustomError {
	ce := BuildError(err)
	if ce == nil {
		return nil
	}
	// Stamp the header *now* (before the envelope is serialised) so it's
	// part of the actual reply, not a post-hoc mutation. We deliberately
	// stamp against the first error only — the Node side does the same.
	c.Set(HeaderErrorType, ce.Context)
	r.AddError(ce)
	return ce
}

