// TestMusicUpdate_MultipleFieldsPreservesOthers 🐛 — patches 4+ fields at
// once; pre-fix would cache ALL of them at pre-update values, so the next
// read would lose every change in a single shot.
func TestMusicUpdate_MultipleFieldsPreservesOthers(t *testing.T) {
	ctx, repo, cache, db := newMusicRepo(t)
	botID, guildID := "bot-mf", "guild-mf"
	seedGuild(t, ctx, db, botID, guildID)

	updated, err := repo.Update(ctx, botID, guildID, map[string]any{
		"volume":            50,
		"loop":              "track",
		"enabled":           false,
		"max_song_duration": 600,
	})
	if err != nil || updated == nil {
		t.Fatalf("update: err=%v src=%+v", err, updated)
	}
	for _, c := range []struct {
		field string
		want  any
	}{
		{"Volume", 50},
		{"Loop", dbguild.MusicLoop("track")},
		{"Enabled", false},
		{"MaxSongDuration", 600},
	} {
		switch w := c.want.(type) {
		case int:
			if getIntField(updated.Data, c.field) != w {
				t.Fatalf("returned %s = %v, want %d", c.field, getIntField(updated.Data, c.field), w)
			}
		case string:
			if getStringField(updated.Data, c.field) != w {
				t.Fatalf("returned %s = %v, want %q", c.field, getStringField(updated.Data, c.field), w)
