package validations

import (
	"regexp"

	"kena.bot/api-db-go/internal/domain/dbbot"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
)

// Request DTOs + parsers for the `/bots` router. Field shapes mirror the Zod
// schemas in `services/api-db/src/domain/zod-schemas/validations/bot-validations.ts`
// and `.../mongo/bot-schema.ts`.
//
// Unlike the `/commands` bodies (which have no top-level defaults and lean on
// struct-tag validation), every bot field carries a zod/mongoose write-time
// default, so the bodies are parsed MANUALLY with pointer fields: a nil pointer
// means "absent" (take the default / skip the `$set`), a non-nil pointer means
// "the client sent this" (validate the enum, force it into the `$set`). This
// reproduces zod's "present-but-invalid → throw, absent → default" semantics
// exactly, which struct tags can't express for optional-with-default fields.

// zodItemError builds the CustomError shape `zodErrorToResultData` produces on
// the Node side: one `ZodItemError` per issue — `context:"ZOD"`, `type:"VALIDATION"`,
// `statusCode:400`, empty `code`, and `metadata.property = issue.path.join(".")`.
// The refine (owner_id-if-custom) has an empty path, so `property` is "".
func zodItemError(message, property string) *apierrors.CustomError {
	return apierrors.New(apierrors.Props{
		Message:    message,
		Context:    apierrors.ContextZod,
		Type:       apierrors.TypeValidation,
		Metadata:   map[string]any{"property": property},
		StatusCode: apierrors.StatusBadRequest,
	})
}

// ParseGetBotsQuery mirrors `queryGetBotsValidation` — the `GET /bots` query:
//
//	type: z.enum(["kena","custom"]).default("custom")
//	owner_id: z.string().optional()
//	.refine(d => d.type !== "custom" || !!d.owner_id,
//	        { message: "owner_id is required when type is custom" })
//
// The params arrive as raw query strings (Fiber's `c.Query` returns "" for
// an absent key). Returns the resolved filter, or the exact `ZodItemError` the
// Node refine/enum path produces. Note the default: an EMPTY query resolves

// Patch mirrors `patchModuleGreeterController`. Strict body; MergeDeepJSON
// (presence-based) semantics on the server side so partial sub-block updates
// (e.g. `welcome.message.content` only) don't clobber siblings, and explicit
// `false`/`0`/`null` leaves are applied (Node parity).
func (h *ModuleGreeterHandler) Patch(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleGreeter]()
	ctx := c.Context()

	var body validations.UpdateModuleGreeterBody
	if err := c.Bind().Body(&body); err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	// El bind sólo comprueba la FORMA (enums, structs anidados). Los topes de
	// longitud y cardinalidad no existían en ninguna capa del servidor: este
	// endpoint acepta un PATCH directo con la credencial de api-db, y sin esto
	// un `message.content` de 1 MB se persistía y dejaba al guild sin
	// bienvenidas para siempre (Discord lo rechaza con 400 y el error sólo
	// aparece en los logs del bot).
	if verr := validations.ValidateUpdateModuleGreeter(&body); verr != nil {
		r.AddError(verr)
		return reply(c, r)
	}

	patch, err := patchMap(c.Body())
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)

		return nil
	}
	return out
}

// RadioModeEnabled is a helper for the controller's PATCH side-effect
// (`redisAdapter.cache.lavalink.setPlayerPersistent`). Returns nil when the
// PATCH body omits `radio_mode` entirely; otherwise a pointer to the new value.
//
// `radio_mode` is whole-object REPLACE, not merge: its fields are values, not
// pointers, so a body carrying `radio_mode` ALWAYS sets `enabled` - omitting
// the field inside it means `false`. That is not a quirk of this helper: `Set`
// above writes that same `false` to Mongo, so the two destinations stay in
// step. The shared TS type (`library-shared/src/db/schemas/DBGuildSchemas.ts`)
// declares both fields required, so no typed client can send the partial.
func (b UpdateModuleMusicBody) RadioModeEnabled() *bool {
	if b.RadioMode == nil {
		return nil
	}
	v := b.RadioMode.Enabled
	return &v
}

