// RadioModeEnabled is a helper for the controller's PATCH side-effect
// (`redisAdapter.cache.lavalink.setPlayerPersistent`). Returns nil when the
// PATCH body omits `radio_mode` entirely; otherwise a pointer to the new value.
//
// `radio_mode` is whole-object REPLACE, not merge: its fields are values, not
// pointers, so a body carrying `radio_mode` ALWAYS sets `enabled` - omitting
// the field inside it means `false`. That is not a quirk of this helper: `Set`
// above writes that same `false` to Mongo, so the two destinations stay in
// step. The shared TS type (`library-shared/src/db/schemas/DBGuildSchemas.ts`)
// declares both fields required, so no typed client can send the partial.
func (b UpdateModuleMusicBody) RadioModeEnabled() *bool {
	if b.RadioMode == nil {
		return nil
	}
	v := b.RadioMode.Enabled
	return &v
}

// musicLoopSet + musicLoopMsg — el enum cerrado de `loop`. `oneof=none song
// queue` vivía como struct tag en `Loop` hasta que se descubrió que nada del
// servicio invoca `validator.Struct` sobre este body (a diferencia de
// `ModuleEnabledQuery`, que sí pasa por `NewValidator().Struct` en el query
// param): la etiqueta era puro adorno, y una cadena vacía o cualquier basura
// se guardaba tal cual. `""` en particular es el peor caso — no es un enum
// legítimo, así que el reproductor no hace nada con ella, pero el documento
// queda con `loop` presente y parece configurado.
var musicLoopSet = map[dbguild.MusicLoop]bool{
	dbguild.MusicLoopNone: true, dbguild.MusicLoopSong: true, dbguild.MusicLoopQueue: true,
}

const musicLoopMsg = `Invalid option: expected one of "none"|"song"|"queue"`

// musicAudioQualitySet + musicAudioQualityMsg — mismo enum cerrado que llevaba
// el `oneof=default hifi` muerto de `AudioQuality`. Ver musicLoopSet.
var musicAudioQualitySet = map[dbguild.MusicAudioQuality]bool{
	dbguild.MusicAudioQualityDefault: true, dbguild.MusicAudioQualityHifi: true,
}

const musicAudioQualityMsg = `Invalid option: expected one of "default"|"hifi"`

// ValidateUpdateModuleMusic aplica las reglas de negocio que sólo vivían en el
// zod del dashboard: este endpoint acepta un PATCH directo con la credencial
// de api-db, así que sin esto un `loop`/`audio_quality` fuera del enum, o un
// `radio_mode.enabled: true` sin canal, se guardaban tal cual — una
// configuración que el bot no puede cumplir (24/7 sin canal en el que
// quedarse) o que no hace nada en silencio (loop/audio_quality desconocidos).
//
// Sólo mira lo que el cuerpo trae: `UpdateModuleMusicBody` es un parcial y un
// puntero nil significa «no tocar este campo», no «vacío».
func ValidateUpdateModuleMusic(body *UpdateModuleMusicBody) *apierrors.CustomError {
	if body == nil {
		return nil
	}

	if body.Loop != nil && !musicLoopSet[*body.Loop] {
		return zodItemError(musicLoopMsg, "loop")
	}

	if body.AudioQuality != nil && !musicAudioQualitySet[*body.AudioQuality] {
		return zodItemError(musicAudioQualityMsg, "audio_quality")
	}

	// `radio_mode` es whole-object REPLACE (ver RadioModeEnabled): un cuerpo
	// que lo trae SIEMPRE fija `enabled`, así que `enabled: true` con

func (h *ModuleMusicHandler) Patch(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleMusic]()
	ctx := c.Context()

	var body validations.UpdateModuleMusicBody
	if err := c.Bind().Body(&body); err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	// El bind sólo comprueba la FORMA. `loop`/`audio_quality` fuera de su enum
	// y `radio_mode.enabled: true` sin canal no existían en ninguna capa del
	// servidor: este endpoint acepta un PATCH directo con la credencial de
	// api-db, y sin esto se guardaban configuraciones que el bot no puede
	// cumplir o que no hacen nada en silencio. Ver ValidateUpdateModuleMusic.
	if verr := validations.ValidateUpdateModuleMusic(&body); verr != nil {
		r.AddError(verr)
		return reply(c, r)
	}

	set := body.Set()
	if len(set) == 0 {
		// Empty body or no applicable fields → 400. Strict parity with
		// the bots-guilds Update handler.
		r.AddError(apierrors.Unknown(""))
